// Takes the pasted listing and builds a request for Claude.
const body = $input.first().json.body || {};
const text = String(body.text || '').slice(0, 6000);
const url = body.url || null;

const prompt = `You extract furniture product data for a budgeting app for first-time movers.
Read the listing below and return ONLY a JSON object, no prose, no code fences, with these keys:
- name: short product name (max 80 chars)
- category: one of bed, wardrobe, drawers, bedside, mirror, floor_lamp, sofa, armchair, coffee_table, tv_stand, bookshelf, desk, office_chair, filing_cabinet, dining_table, dining_chair, sideboard, bath_cabinet, bath_shelf, towel_stand, hamper, stool, shoe_rack, tv, wall_art, wall_shelf, wall_mirror, bath_wall_cabinet, coat_hooks
- price: number in GBP (convert if needed; null if absent)
- w, d, h: width, depth, height in centimetres as numbers (convert mm/inches; width is the longest horizontal side; null if absent)
- colour: a hex colour that best matches the main finish, e.g. "#C49A6C"
- colourName: plain words, e.g. "oak"
- tone: one of light, wood, dark, colour
- styles: 1-2 of minimal, scandi, industrial, cosy, bold
- condition: "new" or "used"
- quality: one of budget, mid, premium (judge from materials, brand positioning, price for the category)

Listing:
"""
${text}
"""`;

return [{ json: { url, request: {
  model: 'claude-haiku-5-5',
  max_tokens: 600,
  messages: [{ role: 'user', content: prompt }]
} } }];

// Parses Claude's answer and adds NestEgg's finance estimates.
const res = $input.first().json;
const text = (res.content || []).filter(c => c.type === 'text').map(c => c.text).join('');
let p;
try {
  p = JSON.parse(text.replace(/```json|```/g, '').trim());
} catch (e) {
  return [{ json: { error: "Couldn't read product details from that listing." } }];
}

// Typical lifespan (years), share of price recovered when resold after ~1 year,
// buying priority for a first-time mover, and rooms it belongs in.
const CATEGORY = {
  bed:            [7, 0.30, 'essential', ['bedroom']],
  wardrobe:       [6, 0.30, 'essential', ['bedroom']],
  drawers:        [6, 0.30, 'soon',      ['bedroom']],
  bedside:        [6, 0.30, 'soon',      ['bedroom']],
  mirror:         [8, 0.35, 'later',     ['bedroom']],
  floor_lamp:     [5, 0.30, 'later',     ['bedroom', 'living_room', 'home_office']],
  sofa:           [6, 0.25, 'essential', ['living_room']],
  armchair:       [6, 0.30, 'soon',      ['living_room']],
  coffee_table:   [8, 0.35, 'soon',      ['living_room']],
  tv_stand:       [7, 0.30, 'later',     ['living_room']],
  bookshelf:      [7, 0.30, 'soon',      ['living_room', 'home_office', 'bedroom']],
  desk:           [6, 0.35, 'essential', ['home_office', 'bedroom']],
  office_chair:   [5, 0.30, 'essential', ['home_office', 'bedroom']],
  filing_cabinet: [10, 0.35, 'later',    ['home_office']],
  dining_table:   [8, 0.35, 'essential', ['dining']],
  dining_chair:   [6, 0.30, 'essential', ['dining']],
  sideboard:      [8, 0.35, 'later',     ['dining', 'living_room']],
  bath_cabinet:   [6, 0.20, 'essential', ['bathroom']],
  bath_shelf:     [4, 0.20, 'soon',      ['bathroom']],
  towel_stand:    [6, 0.25, 'soon',      ['bathroom']],
  hamper:         [3, 0.10, 'later',     ['bathroom', 'bedroom']],
  stool:          [4, 0.20, 'later',     ['bathroom']],
  shoe_rack:      [5, 0.20, 'later',     ['living_room', 'bedroom']],
  tv:             [7, 0.35, 'soon',      ['living_room', 'bedroom']],
  wall_art:       [10, 0.20, 'later',    ['living_room', 'bedroom', 'dining', 'home_office']],
  wall_shelf:     [10, 0.25, 'later',    ['home_office', 'living_room', 'bedroom']],
  wall_mirror:    [10, 0.35, 'later',    ['bedroom', 'bathroom', 'living_room']],
  bath_wall_cabinet: [6, 0.20, 'soon',   ['bathroom']],
  coat_hooks:     [10, 0.20, 'soon',     ['living_room', 'bedroom']],
};
const [life, resale, priority, rooms] = CATEGORY[p.category] || [6, 0.25, 'soon', ['living_room']];

// Better-made furniture lasts longer and holds its value; used items have
// already lost most of their depreciation, so they resell closer to what you paid.
const qualityLife = { budget: 0.7, mid: 1.0, premium: 1.4 }[p.quality] || 1.0;
const qualityResale = { budget: -0.08, mid: 0, premium: 0.1 }[p.quality] || 0;
let resaleRate = resale + qualityResale;
if (p.condition === 'used') resaleRate = Math.min(0.75, resaleRate + 0.3);

return [{ json: {
  name: p.name,
  category: p.category,
  price: p.price,
  w: p.w, d: p.d, h: p.h,
  colour: p.colour,
  colourName: p.colourName,
  tone: p.tone,
  styles: p.styles,
  condition: p.condition,
  rooms,
  priority,
  lifespanYears: Math.round(life * qualityLife * 10) / 10,
  resaleRate: Math.round(Math.max(0.05, resaleRate) * 100) / 100,
  url: $('Build Claude request').first().json.url,
} }];
